const j=$input.first().json.job;
const base='https://api.hubapi.com/crm/v3/objects/contacts';
const id=String(j.provider_contact_id||'');
const attrs=['email','phone','firstname','lastname','hubspot_owner_id','engine1_contact_id','engine1_last_lead_id','engine1_lead_source','engine1_qualification','engine1_engagement','engine1_intent','engine1_priority','engine1_score'];
const props={engine1_contact_id:String(j.contact_id),engine1_last_lead_id:String(j.lead_id),engine1_lead_source:String(j.source||'').slice(0,200),engine1_qualification:String(j.qualification||'').slice(0,240),engine1_engagement:String(j.engagement||'none').slice(0,80),engine1_intent:String(j.intent||'').slice(0,80),engine1_priority:String(j.priority||'').slice(0,50),engine1_score:j.score==null?'':String(j.score),firstname:String(j.first_name||'').slice(0,100)};
if(j.last_name)props.lastname=String(j.last_name).slice(0,100);
if(j.email)props.email=String(j.email).trim().toLowerCase();
if(j.phone)props.phone=String(j.phone).trim();
// An unassigned contact remains unowned; never fabricate an owner ID.
if(j.owner_external_id)props.hubspot_owner_id=String(j.owner_external_id);
let request;
if(id){request={method:'GET',url:base+'/'+encodeURIComponent(id)+'?properties='+attrs.join(','),body:{},mode:'saved_id'};}
else{
 const groups=[];
 if(j.email)groups.push({filters:[{propertyName:'email',operator:'EQ',value:String(j.email).trim().toLowerCase()}]});
 if(j.phone)groups.push({filters:[{propertyName:'phone',operator:'EQ',value:String(j.phone)}]});
 request={method:'POST',url:base+'/search',body:{filterGroups:groups,properties:attrs,limit:10},mode:'identity_search'};
}
return [{json:{job:j,request,props}}];

const p=$('H3 · Prepare HubSpot Identity Lookup').first().json,j=p.job,req=p.request,props=p.props;
const r=$input.first().json||{};let body=r.body||{};
if(typeof body==='string'){try{body=JSON.parse(body)}catch{body={}}}
const status=Number(r.statusCode||r.response?.statusCode||0);
const fail=(result,error)=>[{json:{next:'finish',result,error:String(error).slice(0,100),http_status:status,provider_id:null,outbox_id:j.outbox_id,token:j.token}}];
if(!status)return fail('retryable','hubspot_read_transport_error');
if([401,403].includes(status))return fail('auth','hubspot_read_auth_'+status);
if(status===429||status>=500)return fail('retryable','hubspot_read_retry_'+status);
if(req.mode==='saved_id'&&status===404)return fail('identity_conflict','hubspot_saved_id_not_found');
if(status!==200)return fail('permanent','hubspot_read_http_'+status);
const results=req.mode==='saved_id'?[body]:Array.isArray(body.results)?body.results:[];
if(results.length>1)return fail('identity_conflict','hubspot_multiple_identity_matches');
const o=results[0]||null;
let provider_id=o?String(o.id||''):'';
if(o&&!provider_id)return fail('unknown','hubspot_read_missing_record_id');
if(o){
 const actual=o.properties||{};
 if(actual.engine1_contact_id&&String(actual.engine1_contact_id)!==String(j.contact_id))return fail('identity_conflict','hubspot_contact_id_conflict');
 if(j.email&&actual.email&&String(actual.email).toLowerCase()!==String(j.email).toLowerCase())return fail('identity_conflict','hubspot_email_conflict');
 // Exact identity search includes phone, so a record with a different email is not adopted.
 if(req.mode==='saved_id'&&String(j.provider_contact_id)!==provider_id)return fail('identity_conflict','hubspot_saved_id_mismatch');
 const same=Object.entries(props).every(([k,v])=>String(actual[k]??'')===String(v??''))&&
   (j.owner_external_id||'')===String(actual.hubspot_owner_id||'');
 if(same)return [{json:{next:'finish',result:'done',error:null,http_status:200,provider_id,outbox_id:j.outbox_id,token:j.token}}];
}
const method=o?'PATCH':'POST';
const url=o?'https://api.hubapi.com/crm/v3/objects/contacts/'+encodeURIComponent(provider_id):
 'https://api.hubapi.com/crm/v3/objects/contacts/batch/upsert';
const writeProps={...props};
if(o&&!j.owner_external_id&&o.properties?.hubspot_owner_id)writeProps.hubspot_owner_id=''; // clear stale owner on known record
const b=o?{properties:writeProps}:{inputs:[{id:String(j.contact_id),idProperty:'engine1_contact_id',properties:writeProps}]};
return [{json:{next:'write',outbox_id:j.outbox_id,token:j.token,expected_id:provider_id,method,url,request_body:b,mode:o?'patch':'unique_upsert'}}];

const d=$('H5 · Resolve HubSpot Match or Conflict').first().json;
const r=$input.first().json||{};let b=r.body||{};if(typeof b==='string'){try{b=JSON.parse(b)}catch{b={}}}
const s=Number(r.statusCode||r.response?.statusCode||0);
let id='';let result='unknown',error='hubspot_write_unknown';
if([200,201].includes(s)){
 const candidate=d.mode==='unique_upsert'?(Array.isArray(b.results)?b.results[0]:null):b;
 id=String(candidate?.id||'');
 if(id&&(d.expected_id===''||id===d.expected_id)){result='done';error=null;}
 else {result='unknown';error='hubspot_success_missing_or_changed_id';}
}else if(s===429){result='retryable';error='hubspot_rate_limited';}
else if([401,403].includes(s)){result='auth';error='hubspot_auth_'+s;}
else if([409,422].includes(s)){result='identity_conflict';error='hubspot_identity_or_property_conflict_'+s;}
else if(s>=400&&s<500){result='permanent';error='hubspot_write_http_'+s;}
else if(s>=500||!s){result='unknown';error='hubspot_write_ambiguous_'+(s||'transport');}
return [{json:{outbox_id:d.outbox_id,token:d.token,provider_id:id||null,result,error,http_status:s||null}}];

const j=$input.first().json.job;
const base='https://services.leadconnectorhq.com';
const loc=String(j.ghl_location_id||'');const id=String(j.provider_contact_id||'');
const dup=(key,val)=>base+'/contacts/search/duplicate?locationId='+encodeURIComponent(loc)+'&'+key+'='+encodeURIComponent(String(val));
const u1=id?base+'/contacts/'+encodeURIComponent(id):j.email?dup('email',j.email):dup('number',j.phone);
// A separate second read catches email-vs-phone split identity collisions.
const u2=j.phone?dup('number',j.phone):u1;
return [{json:{job:j,lookup_mode:id?'saved_id':'duplicate',lookup1:u1,lookup2:u2}}];

const p=$('G3 · Prepare GHL Identity Lookups').first().json,j=p.job;
const r1=$('G4 · GHL Read Saved ID or Email').first().json||{},r2=$input.first().json||{};
const un=r=>{let b=r.body||{};if(typeof b==='string'){try{b=JSON.parse(b)}catch{b={}}}return {status:Number(r.statusCode||r.response?.statusCode||0),body:b}};
const a=un(r1),b=un(r2);
const fail=(result,error,http_status)=>[{json:{next:'finish',result,error,http_status,provider_id:null,outbox_id:j.outbox_id,token:j.token}}];
for(const z of [a,b]){
 if(!z.status)return fail('retryable','ghl_identity_transport_error',null);
 if([401,403].includes(z.status))return fail('auth','ghl_identity_auth_'+z.status,z.status);
 if(z.status===429||z.status>=500)return fail('retryable','ghl_identity_retry_'+z.status,z.status);
 if(z.status!==200)return fail(z.status===404&&p.lookup_mode==='saved_id'?'identity_conflict':'permanent',
     'ghl_identity_http_'+z.status,z.status);
}
const c1=a.body?.contact||null,c2=b.body?.contact||null;
const id1=String(c1?.id||''),id2=String(c2?.id||'');
if(id1&&id2&&id1!==id2)return fail('identity_conflict','ghl_email_phone_split_identity',200);
if(p.lookup_mode==='saved_id'&&!id1)return fail('identity_conflict','ghl_saved_id_missing',200);
const c=c1||c2||null,id=String(c?.id||'');
if(j.provider_contact_id&&id&&id!==String(j.provider_contact_id))return fail('identity_conflict','ghl_saved_id_conflict',200);
if(c&&c.locationId&&String(c.locationId)!==String(j.ghl_location_id))return fail('identity_conflict','ghl_wrong_location',200);
if(c&&j.email&&c.email&&String(c.email).toLowerCase()!==String(j.email).toLowerCase())return fail('identity_conflict','ghl_email_conflict',200);
const fields=j.ghl_fields||{};
const values={engine1_contact_id:String(j.contact_id),last_lead_id:String(j.lead_id),
 qualification:String(j.qualification||'').slice(0,240),engagement:String(j.engagement||'none'),
 intent:String(j.intent||''),priority:String(j.priority||''),score:j.score==null?'':String(j.score)};
const customFields=Object.entries(values).map(([k,value])=>({id:String(fields[k]),fieldValue:String(value)}));
const actual=new Map((Array.isArray(c?.customFields)?c.customFields:[]).map(x=>[String(x.id||''),String(x.value??x.fieldValue??'')]));
const existingEngine1Id=actual.get(String(fields.engine1_contact_id));
if(existingEngine1Id&&existingEngine1Id!==String(j.contact_id))return fail('identity_conflict','ghl_engine1_identity_conflict',200);
const payload={firstName:String(j.first_name||'Customer').slice(0,100),source:String(j.source||'').slice(0,150),customFields};
if(j.last_name)payload.lastName=String(j.last_name).slice(0,100);
if(j.email)payload.email=String(j.email);
if(j.phone)payload.phone=String(j.phone);
if(!id)payload.locationId=String(j.ghl_location_id);
if(j.owner_external_id)payload.assignedTo=String(j.owner_external_id);
else if(id&&c?.assignedTo)payload.assignedTo=null; // clear stale owner on known existing contact
if(!id)payload.createNewIfDuplicateAllowed=false;
const same=id&&String(c?.firstName||'')===String(payload.firstName||'')&&
 String(c?.source||'')===String(payload.source||'')&&
 (!j.owner_external_id?(!c?.assignedTo):String(c?.assignedTo||'')===String(j.owner_external_id))&&
 Object.entries(values).every(([k,val])=>actual.get(String(fields[k]))===String(val));
if(same)return [{json:{next:'finish',result:'done',error:null,http_status:200,provider_id:id,outbox_id:j.outbox_id,token:j.token}}];
return [{json:{next:'write',outbox_id:j.outbox_id,token:j.token,expected_id:id,
 method:id?'PUT':'POST',url:id?'https://services.leadconnectorhq.com/contacts/'+encodeURIComponent(id):
 'https://services.leadconnectorhq.com/contacts/upsert',request_body:payload}}];

const d=$('G6 · Resolve GHL Match or Conflict').first().json;
const r=$input.first().json||{};let b=r.body||{};if(typeof b==='string'){try{b=JSON.parse(b)}catch{b={}}}
const s=Number(r.statusCode||r.response?.statusCode||0);
let id=String(b.contact?.id||'');let result='unknown',error='ghl_write_unknown';
if([200,201].includes(s)&&b.succeeded!==false&&b.succeded!==false){
 if(id&&(!d.expected_id||d.expected_id===id)){result='done';error=null;}
 else {result='unknown';error='ghl_success_missing_or_changed_contact_id';}
}else if(s===429){result='retryable';error='ghl_rate_limited';}
else if([401,403].includes(s)){result='auth';error='ghl_auth_'+s;}
else if([409,422].includes(s)){result='identity_conflict';error='ghl_duplicate_or_field_conflict_'+s;}
else if(s>=400&&s<500){result='permanent';error='ghl_write_http_'+s;}
else if(s>=500||!s){result='unknown';error='ghl_write_ambiguous_'+(s||'transport');}
return [{json:{outbox_id:d.outbox_id,token:d.token,provider_id:id||null,result,error,http_status:s||null}}];
